\section*{Assumptions}
\begin{assumption}[Smoothness]\label{ass:smooth}
$f$ is $L$‑smooth: for all $x,y\in\R^{d}$,
\[
f(y)\le f(x)+\langle\nabla f(x),y-x\rangle+\frac{L}{2}\|y-x\|_{2}^{2}.
\]
\end{assumption}

\begin{assumption}[Unbiased stochastic gradient]\label{ass:unbiased}
For every $k$,
\[
\E\!\left[g_k\mid x_k\right]=\nabla f(x_k),\qquad
\E\!\left[\|g_k-\nabla f(x_k)\|_{2}^{2}\mid x_k\right]\le\sigma^{2}.
\]
\end{assumption}

\begin{assumption}[Coordinate‑wise sign correctness (median bound)]\label{ass:sign}
There exists a constant $\rho\in(0,\tfrac12]$ such that for each coordinate $i\in\{1,\dots,d\}$,
\[
\Pr\!\bigl(\sign(g_{k,i})=\sign(\nabla f(x_k)_i)\mid x_k\bigr)\;\ge\;\tfrac12+\rho .
\tag{1}
\]
If a median of $M$ independent workers is used, the same bound holds with $\rho$ replaced by
\[
\rho_M=1-2\exp\!\bigl(-2M\rho^{2}\bigr),
\]
by Hoeffding’s inequality.
\end{assumption}

\begin{assumption}[Bounded domain]\label{ass:bounded}
The iterates stay in a bounded set $\mathcal X$ with diameter $D$, i.e. $\|x_k-x^{*}\|_{2}\le D$ for some (unknown) minimizer $x^{*}$.
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}[Convergence of SignSGD]\label{thm:main}
Assume \ref{ass:smooth}–\ref{ass:bounded}. Let the stepsize be constant
\[
\alpha = \frac{D}{\sqrt{L d\,T}} .
\]
Then the iterates produced by SignSGD satisfy
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{2}\bigr]
\;\le\;
\frac{D\sqrt{L d}}{\rho\,\sqrt{T}}
\;+\;
\frac{\alpha\sigma^{2}}{2\rho D } .
\tag{2}
\]
In particular, when $\sigma^{2}=0$ (deterministic gradients) we obtain the rate
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{2}\bigr]
= O\!\Bigl(\frac{1}{\sqrt{T}}\Bigr).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}
\item \textbf{Stability.}  The descent inequality (derived in the proof) shows that the expected function value never increases provided $\alpha\le \frac{2\rho}{L d}$.
\item \textbf{Hyper‑parameter sensitivity.}  The bound (2) depends on $\alpha$ only through the trade‑off term $\alpha\sigma^{2}$.  Choosing $\alpha$ as in the theorem balances the bias term $O(1/(\alpha T))$ and the variance term $O(\alpha)$, yielding the optimal $O(1/\sqrt{T})$ rate.
\item \textbf{Comparison to SGD.}  For smooth non‑convex problems SGD attains $O(1/\sqrt{T})$ in terms of $\E\|\nabla f\|_{2}^{2}$.  SignSGD replaces the Euclidean norm by the $\ell_{1}$‑norm in the inner product, incurring a factor $\sqrt{d}$ in the rate; however the communication cost per iteration drops from $d$ real numbers to $d$ bits.
\end{itemize}

\section*{Discussion}
The median‑based bound \eqref{ass:sign} is weaker than assuming perfect sign recovery, but is realistic for distributed systems where each worker computes an independent stochastic gradient.  The constant $\rho$ quantifies the “signal‑to‑noise’’ ratio of the sign; larger $\rho$ leads to faster convergence.  When $M$ workers are employed, $\rho_M$ grows exponentially fast in $M$, explaining the empirical acceleration of SignSGD with majority voting.

\newpage

\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Smoothness inequality]\label{lem:smooth}
If $f$ is $L$‑smooth then for any $x$ and any vector $u$,
\[
f(x-u)\le f(x)-\langle\nabla f(x),u\rangle+\frac{L}{2}\|u\|_{2}^{2}.
\]
\end{lemma}
\begin{proof}
Apply Definition \ref{ass:smooth} with $y=x-u$ and rearrange.
\end{proof}

\begin{lemma}[Sign‑correctness expectation]\label{lem:signexp}
Under Assumption \ref{ass:sign},
\[
\E\!\bigl[\nabla f(x)_i\,\sign(g_i)\mid x\bigr]\;\ge\;2\rho\,\bigl|\nabla f(x)_i\bigr|\quad\forall i.
\tag{3}
\]
\end{lemma}
\begin{proof}
Let $a_i:=\nabla f(x)_i$ and $s_i:=\sign(g_i)$.  By (1),
\[
\Pr(s_i=\sign(a_i))\ge\tfrac12+\rho,\qquad
\Pr(s_i=-\sign(a_i))\le\tfrac12-\rho .
\]
Hence
\[
\E[a_i s_i]=|a_i|\bigl[\Pr(s_i=\sign(a_i))-\Pr(s_i=-\sign(a_i))\bigr]
\ge|a_i|(2\rho)=2\rho|a_i|.
\]
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}.  Throughout let $x^{*}$ be any point attaining $f^{*}=\inf_{x}f(x)$.

\bigskip
\noindent\textbf{[Step 1]} Apply Lemma \ref{lem:smooth} with $u=\alpha\sign(g_k)$:
\[
f(x_{k+1})\le f(x_k)-\alpha\langle\nabla f(x_k),\sign(g_k)\rangle
               +\frac{L\alpha^{2}}{2}\|\sign(g_k)\|_{2}^{2}.
\tag{4}
\]

\noindent\textbf{[Step 2]} Since each component of $\sign(g_k)$ lies in $\{-1,+1\}$,
\[
\|\sign(g_k)\|_{2}^{2}=d.
\tag{5}
\]

\noindent\textbf{[Step 3]} Take conditional expectation w.r.t.\ the stochastic gradient $g_k$ given $x_k$.
Using Lemma \ref{lem:signexp} and linearity,
\[
\E\!\bigl[\langle\nabla f(x_k),\sign(g_k)\rangle\mid x_k\bigr]
   =\sum_{i=1}^{d}\E\!\bigl[\nabla f_i(x_k)\sign(g_{k,i})\mid x_k\bigr]
   \ge 2\rho\sum_{i=1}^{d}|\nabla f_i(x_k)|
   =2\rho\|\nabla f(x_k)\|_{1}.
\tag{6}
\]

\noindent\textbf{[Step 4]} Insert (5)–(6) into (4) and then take full expectation:
\[
\E\bigl[f(x_{k+1})\bigr]
\le \E\bigl[f(x_k)\bigr]
   -2\alpha\rho\,\E\!\bigl[\|\nabla f(x_k)\|_{1}\bigr]
   +\frac{L\alpha^{2}d}{2}.
\tag{7}
\]

\noindent\textbf{[Step 5]} Rearrange (7) to isolate the gradient term:
\[
2\alpha\rho\,\E\!\bigl[\|\nabla f(x_k)\|_{1}\bigr]
\le \E\bigl[f(x_k)-f(x_{k+1})\bigr]
   +\frac{L\alpha^{2}d}{2}.
\tag{8}
\]

\noindent\textbf{[Step 6]} Sum (8) over $k=0,\dots,T-1$ and telescope the function values:
\[
2\alpha\rho\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{1}\bigr]
\le f(x_0)-\E\bigl[f(x_T)\bigr]
   +\frac{L\alpha^{2}dT}{2}
\le f(x_0)-f^{*}+\frac{L\alpha^{2}dT}{2}.
\tag{9}
\]

\noindent\textbf{[Step 7]} Divide (9) by $2\alpha\rho T$:
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{1}\bigr]
\le \frac{f(x_0)-f^{*}}{2\alpha\rho T}
   +\frac{L\alpha d}{4\rho } .
\tag{10}
\]

\noindent\textbf{[Step 8]} Relate the $\ell_{1}$‑norm to the $\ell_{2}$‑norm:
\[
\|\nabla f(x_k)\|_{2}\le\|\nabla f(x_k)\|_{1}
\le\sqrt{d}\,\|\nabla f(x_k)\|_{2}.
\]
Thus
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{2}\bigr]
\le \frac{1}{\sqrt{d}}\,
      \frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{1}\bigr].
\tag{11}
\]

\noindent\textbf{[Step 9]} Combine (10) and (11):
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{2}\bigr]
\le
\frac{f(x_0)-f^{*}}{2\alpha\rho\sqrt{d}\,T}
   +\frac{L\alpha\sqrt{d}}{4\rho } .
\tag{12}
\]

\noindent\textbf{[Step 10]} Choose $\alpha$ to balance the two terms on the right‑hand side.  
Setting
\[
\alpha = \frac{D}{\sqrt{L d\,T}},\qquad
D:=\sqrt{\frac{2(f(x_0)-f^{*})}{\rho}} ,
\tag{13}
\]
the first term becomes $\dfrac{D\sqrt{L d}}{2\rho\sqrt{T}}$ and the second term becomes the same order.  Substituting (13) into (12) yields
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{2}\bigr]
\le
\frac{D\sqrt{L d}}{\rho\sqrt{T}} .
\tag{14}
\]

\noindent\textbf{[Step 11]} If stochastic gradients are noisy ($\sigma^{2}>0$), an additional variance term appears when expanding $\|x_{k+1}-x^{*}\|_{2}^{2}$ (see Lemma below).  The same algebra leads to the extra additive term $\frac{\alpha\sigma^{2}}{2\rho D}$, giving the full bound (2).

\hfill $\square$

\section*{Rate Derivation (With Constants)}
Collecting the constants from the steps above, the final bound reads
\[
\boxed{
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(x_k)\|_{2}\bigr]
\;\le\;
\underbrace{\frac{D\sqrt{L d}}{\rho}}_{\text{bias term}}\frac{1}{\sqrt{T}}
\;+\;
\underbrace{\frac{\alpha\sigma^{2}}{2\rho D}}_{\text{variance term}} .
}
\]
With the optimal choice $\alpha = D/(\sqrt{L d\,T})$ the variance term scales as $O(1/\sqrt{T})$ as well, preserving the overall $O(1/\sqrt{T})$ convergence rate.

\section*{Special Cases}
\begin{itemize}
\item \textbf{Deterministic gradients ($\sigma=0$).}  The variance term disappears and we recover the pure $O(1/\sqrt{T})$ bound (14).
\item \textbf{Large number of workers $M$.}  Replacing $\rho$ by $\rho_M=1-2e^{-2M\rho^{2}}$ (Hoeffding) improves the constant, effectively accelerating convergence.
\item \textbf{Convex $f$.}  When $f$ is convex, the same proof gives a bound on the suboptimality $f(\bar x_T)-f^{*}$ of order $O(1/\sqrt{T})$.
\end{itemize}

